                  </tbody>
                </table>
              </td>
            </tr>
          </tbody>
        </table>
      </td>
    </tr>
  </tbody>
</table>`;
}

const recipientEmail = clean(body.recipientEmail, 260).toLowerCase();
const subject = clean(body.subject, 260);
const html = clean(body.html, 12000);
const text = clean(body.text, 12000);
const idempotencyKey = clean(body.idempotencyKey, 260);
const attachment = body.attachment || {};
const attachmentBase64 = clean(attachment.contentBase64, 15 * 1024 * 1024);
const attachmentFilename = clean(attachment.filename, 180) || 'auftragsbestaetigung.pdf';
const attachmentContentType = clean(attachment.contentType, 120) || 'application/pdf';

if (body.kind !== 'supplier_order_confirmation') errors.push('kind must be supplier_order_confirmation');
if (!clean(body.saleId, 120)) errors.push('saleId missing');
if (!isEmail(recipientEmail)) errors.push('recipientEmail invalid');
if (!subject) errors.push('subject missing');
if (!html && !text) errors.push('html/text missing');
if (!idempotencyKey) errors.push('idempotencyKey missing');
if (!attachmentBase64) errors.push('attachment.contentBase64 missing');
if (attachmentContentType !== 'application/pdf') errors.push('attachment must be PDF');
if (!/\.pdf$/i.test(attachmentFilename)) errors.push('attachment filename must end with .pdf');
if (recipientEmail.endsWith('@neontrip.test')) errors.push('test recipient blocked');

if (errors.length) {
  return [{
    json: {
      valid: false,
      statusCode: 400,
      error: errors.join('; '),
      idempotencyKey: idempotencyKey || null,
      saleId: clean(body.saleId, 120) || null
    }
  }];
}

const bodyHtml = html || `<p>${escapeHtml(text).replace(/\n/g, '<br>')}</p>`;
const fullHtml = `${bodyHtml}${signatureHtml()}`;

return [{
  json: {
    valid: true,
    saleId: clean(body.saleId, 120),
    idempotencyKey,
    recipientEmail,
    subject,
    bodyHtml: fullHtml,
    requestedBy: clean(body.requestedBy, 120) || null,
    attachmentSha256: clean(attachment.sha256, 80) || null
  },
  binary: {
    orderConfirmationPdf: {
      data: attachmentBase64,
      mimeType: attachmentContentType,
      fileName: attachmentFilename
    }
  }
}];
